'use client';



import { useEffect, useMemo, useState } from 'react';

import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';

import { Activity, ArrowDownRight, ArrowUpRight, BarChart3, Boxes, ChevronDown, CircleHelp, Download, FileSpreadsheet, LayoutDashboard, Lightbulb, LoaderCircle, LogOut, Package, Search, Send, Settings, ShieldCheck, Sparkles, Upload, WalletCards } from 'lucide-react';



const API = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000';

type Facts = { period: {start:string;end:string}; comparison:any; metrics: Record<string, any>; inventory_cost_value:any; top_products_by_sales:any[]; top_products_by_profit:any[]; low_stock:any[]; reorder_suggestions:any[]; action_center:any[]; trend:any[]; limitations:string[] };

type Section='Overview'|'Sales analytics'|'Products'|'Inventory'|'Finance'|'Marketing insights'|'Ask StockSense'|'Reports'|'Imports'|'Settings';

type ChatMessage={question:string;answer?:string;evidence?:any;loading?:boolean};

const nav: {name:Section;icon:any}[]=[{name:'Overview',icon:LayoutDashboard},{name:'Sales analytics',icon:BarChart3},{name:'Products',icon:Package},{name:'Inventory',icon:Boxes},{name:'Finance',icon:WalletCards},{name:'Marketing insights',icon:Sparkles},{name:'Ask StockSense',icon:Lightbulb},{name:'Reports',icon:FileSpreadsheet},{name:'Imports',icon:Upload},{name:'Settings',icon:Settings}];

const money=(n:any)=>n==null?'—':new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(n));

const fmt=(n:any)=>n==null?'Insufficient data':new Intl.NumberFormat('en-IN',{maximumFractionDigits:1}).format(Number(n));

async function api(path:string,init?:RequestInit){const r=await fetch(API+path,{...init,credentials:'include'});if(!r.ok){let m='Request failed';try{m=(await r.json()).detail||m}catch{}throw new Error(m)}return r;}



export default function Home(){

 const [section,setSection]=useState<Section>('Overview'),[authMode,setAuthMode]=useState<'login'|'register'>('register'),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[workspaceName,setWorkspaceName]=useState(''),[storeName,setStoreName]=useState(''),[authBusy,setAuthBusy]=useState(false),[facts,setFacts]=useState<Facts|null>(null),[marketing,setMarketing]=useState<any>(null),[user,setUser]=useState<any>(null),[ai,setAi]=useState<any>(null),[products,setProducts]=useState<any[]>([]),[stores,setStores]=useState<any[]>([]),[storeId,setStoreId]=useState(''),[movements,setMovements]=useState<any[]>([]),[movementType,setMovementType]=useState('count'),[movementProduct,setMovementProduct]=useState(''),[movementQuantity,setMovementQuantity]=useState(''),[movementNote,setMovementNote]=useState(''),[movementBusy,setMovementBusy]=useState(false),[loading,setLoading]=useState(true),[error,setError]=useState(''),[start,setStart]=useState(''),[end,setEnd]=useState(''),[query,setQuery]=useState(''),[chatMessages,setChatMessages]=useState<ChatMessage[]>([]),[asking,setAsking]=useState(false),[question,setQuestion]=useState(''),[file,setFile]=useState<File|null>(null),[preview,setPreview]=useState<any>(null),[notice,setNotice]=useState(''),[budget,setBudget]=useState('20000'),[budgetPlan,setBudgetPlan]=useState<any>(null);

 const dateParams=useMemo(()=>{const p=new URLSearchParams();if(start&&end){p.set('start',start);p.set('end',end)}if(storeId)p.set('store_id',storeId);return p.size?`?${p.toString()}`:''},[start,end,storeId]);

const refresh=async()=>{setLoading(true);setError('');try{const me=await api('/api/auth/me');setUser(await me.json());const storeResponse=await api('/api/stores');const availableStores=await storeResponse.json();setStores(availableStores);const selected=storeId||String(availableStores[0]?.id||'');if(selected&&!storeId)setStoreId(selected);const p=new URLSearchParams();if(start&&end){p.set('start',start);p.set('end',end)}if(selected)p.set('store_id',selected);const f=await api('/api/analytics/overview'+(p.size?`?${p.toString()}`:''));setFacts(await f.json());const s=await api('/api/ai/status');setAi(await s.json());const productsUrl=selected?`/api/products?store_id=${selected}`:'/api/products';const productsResponse=await api(productsUrl);setProducts(await productsResponse.json());const movementUrl=selected?`/api/inventory/movements?store_id=${selected}&limit=30`:'/api/inventory/movements?limit=30';const movementResponse=await api(movementUrl);setMovements(await movementResponse.json())}catch(e:any){setError(['Please sign in','Session expired','User not found'].includes(e.message)?'':e.message)}finally{setLoading(false)}};

 useEffect(()=>{refresh()},[dateParams]);

 useEffect(()=>{if(section==='Marketing insights'&&user){api('/api/analytics/marketing'+dateParams).then(async r=>setMarketing(await r.json())).catch((e:any)=>setError(e.message))}},[section,dateParams,user]);

 const submitAuth=async(e:any)=>{e.preventDefault();setAuthBusy(true);setError('');try{await api(authMode==='register'?'/api/auth/register':'/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(authMode==='register'?{email,password,workspace_name:workspaceName,store_name:storeName}:{email,password})});await refresh()}catch(e:any){setError(e.message)}finally{setAuthBusy(false)}};

 const signOut=async()=>{await api('/api/auth/logout',{method:'POST'});setUser(null);setFacts(null)};

 const ask=async(e:any)=>{e.preventDefault();const submitted=question.trim();if(!submitted||asking)return;const messageIndex=chatMessages.length;setChatMessages(prev=>[...prev,{question:submitted,loading:true}]);setQuestion('');setAsking(true);try{const fd=new FormData();fd.append('question',submitted);const r=await api('/api/ai/chat'+dateParams,{method:'POST',body:fd});const j=await r.json();setChatMessages(prev=>prev.map((message,index)=>index===messageIndex?{question:submitted,answer:j.answer,evidence:{...j.evidence,period:j.period,answer_source:j.answer_source,model:j.model}}:message))}catch(e:any){setChatMessages(prev=>prev.map((message,index)=>index===messageIndex?{question:submitted,answer:e.message}:message))}finally{setAsking(false)}};

 const recordMovement=async(e:any)=>{e.preventDefault();if(!movementProduct||movementQuantity===''||movementBusy)return;setMovementBusy(true);setError('');try{await api('/api/inventory/movements',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({product_id:Number(movementProduct),movement_type:movementType,quantity:Number(movementQuantity),note:movementNote||null})});setNotice(movementType==='count'?'Stock count saved with an audit entry.':movementType==='receive'?'Delivery recorded and on-hand stock updated.':movementType==='damage'?'Damaged units recorded and removed from on-hand stock.':'Stock correction saved with an audit entry.');setMovementQuantity('');setMovementNote('');await refresh()}catch(e:any){setError(e.message)}finally{setMovementBusy(false)}};

 const saveProductCost=async(productId:number,rawValue:string)=>{const unit_cost=rawValue===''?null:Number(rawValue);if(unit_cost!==null&&(!Number.isFinite(unit_cost)||unit_cost<0)){setError('Unit cost must be zero or greater.');return}try{await api(`/api/products/${productId}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({unit_cost})});setNotice('Product cost saved for inventory valuation and reorder budgeting. Gross-profit analysis still needs the cost recorded on each sale line.');await refresh()}catch(e:any){setError(e.message)}};

 const planBudget=async(e:any)=>{e.preventDefault();setBudgetPlan(null);try{const fd=new FormData();fd.append('budget',budget);const r=await api('/api/analytics/budget-plan'+dateParams,{method:'POST',body:fd});setBudgetPlan(await r.json())}catch(e:any){setError(e.message)}};

 const showReport=async()=>{try{const r=await api('/api/reports'+dateParams,{method:'POST'});const blob=await r.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='stocksense-report.csv';a.click();URL.revokeObjectURL(a.href)}catch(e:any){setError(e.message)}};

 const previewImport=async()=>{if(!file)return;try{const fd=new FormData();fd.append('file',file);const r=await api('/api/imports/preview',{method:'POST',body:fd});setPreview(await r.json());setNotice('Review the detected columns, then confirm to import valid rows.')}catch(e:any){setError(e.message)}};

 const confirmImport=async()=>{if(!file||!preview)return;try{const fd=new FormData();fd.append('file',file);const mapping=Object.fromEntries(Object.entries(preview.suggested_mapping).filter(([,v])=>Boolean(v)));fd.append('mapping_json',JSON.stringify(mapping));const r=await api('/api/imports/confirm',{method:'POST',body:fd});const j=await r.json();setNotice(`${j.imported_rows} rows imported · ${j.rejected_rows} rejected`);setPreview(null);setFile(null);await refresh()}catch(e:any){setError(e.message)}};

 const m=facts?.metrics;

 const statCards=[['Net sales',money(m?.net_sales),'Gross sales − discounts − returns; tax excluded.',<WalletCards size={18}/>],['Gross profit',money(m?.gross_profit),'Net sales − COGS. Unavailable when costs are incomplete.',<Activity size={18}/>],['Gross margin',m?.gross_margin_pct==null?'Insufficient data':`${fmt(m.gross_margin_pct)}%`,'Gross profit ÷ net sales × 100.',<BarChart3 size={18}/>],['Units sold',fmt(m?.net_units),'Gross units sold, net of recorded returns.',<Package size={18}/>]] as any[];

 if(facts?.comparison?.net_sales_growth_pct!=null) statCards[0][2]+=` ${Number(facts.comparison.net_sales_growth_pct)>=0?'+':''}${fmt(facts.comparison.net_sales_growth_pct)}% vs previous equal-length period.`;

 if(facts?.comparison?.gross_profit_growth_pct!=null) statCards[1][2]+=` ${Number(facts.comparison.gross_profit_growth_pct)>=0?'+':''}${fmt(facts.comparison.gross_profit_growth_pct)}% vs previous equal-length period.`;

 if(loading&&!user) return <div className="grid min-h-screen place-items-center text-sm text-slate-400">Loading StockSense…</div>;

 if(!user) return <div className="min-h-screen grid place-items-center p-6"><div className="w-full max-w-md rounded-3xl bg-white p-8 shadow-soft sm:p-9"><div className="mb-6 flex h-12 w-12 items-center justify-center rounded-2xl bg-mint text-forest"><Boxes/></div><div className="text-xs font-bold uppercase tracking-[.18em] text-forest">StockSense AI</div><h1 className="mt-3 text-3xl font-semibold">{authMode==='register'?'Set up your workspace':'Welcome back'}</h1><p className="mt-3 text-sm leading-6 text-slate-500">{authMode==='register'?'Create your account to start with an empty store workspace, then add products or import your sales.':'Sign in to view your store data.'}</p><form onSubmit={submitAuth} className="mt-6 space-y-3">{authMode==='register'&&<><input required minLength={2} maxLength={160} value={workspaceName} onChange={e=>setWorkspaceName(e.target.value)} placeholder="Business or workspace name" className="w-full rounded-xl border border-slate-200 px-4 py-3 text-sm"/><input required minLength={2} maxLength={160} value={storeName} onChange={e=>setStoreName(e.target.value)} placeholder="First store name" className="w-full rounded-xl border border-slate-200 px-4 py-3 text-sm"/></>}<input required type="email" autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="Email address" className="w-full rounded-xl border border-slate-200 px-4 py-3 text-sm"/><input required type="password" minLength={authMode==='register'?10:1} autoComplete={authMode==='register'?'new-password':'current-password'} value={password} onChange={e=>setPassword(e.target.value)} placeholder={authMode==='register'?'Password (at least 10 characters)':'Password'} className="w-full rounded-xl border border-slate-200 px-4 py-3 text-sm"/>{error&&<p role="alert" className="rounded-lg bg-red-50 px-3 py-2 text-xs text-red-700">{error}</p>}<button disabled={authBusy} className="w-full rounded-xl bg-forest px-4 py-3 font-semibold text-white hover:bg-emerald-800 disabled:opacity-50">{authBusy?'Please wait…':authMode==='register'?'Create workspace':'Sign in'}</button></form><button onClick={()=>{setAuthMode(authMode==='register'?'login':'register');setError('')}} className="mt-4 w-full text-center text-xs text-forest underline">{authMode==='register'?'Already have an account? Sign in':'New to StockSense? Create a workspace'}</button></div></div>;

 return <div className="min-h-screen lg:flex">

  <aside className="hidden w-[248px] shrink-0 border-r border-slate-200/70 bg-white px-4 py-6 lg:sticky lg:top-0 lg:flex lg:h-screen lg:flex-col lg:overflow-y-auto lg:overscroll-contain"><div className="flex items-center gap-3 px-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-forest text-white"><Boxes size={22}/></div><div><div className="font-bold tracking-tight">StockSense <span className="text-forest">AI</span></div><div className="mt-0.5 text-[10px] font-semibold uppercase tracking-[.16em] text-slate-400">Retail intelligence</div></div></div><div className="mt-8 px-3 text-[10px] font-bold uppercase tracking-[.16em] text-slate-400">Workspace</div><nav className="mt-3 space-y-1">{nav.map(({name,icon:Icon})=><button key={name} onClick={()=>setSection(name)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-[13px] font-medium ${section===name?'bg-mint text-forest':'text-slate-500 hover:bg-slate-50 hover:text-ink'}`}><Icon size={17}/>{name}{name==='Ask StockSense'&&<span className="ml-auto rounded-md bg-white px-1.5 py-0.5 text-[9px] font-bold text-forest">AI</span>}</button>)}</nav><div className="mt-auto rounded-2xl border border-emerald-100 bg-emerald-50/70 p-4"><div className="flex items-center gap-2 text-xs font-semibold text-forest"><ShieldCheck size={15}/> Your data stays yours</div><p className="mt-2 text-[11px] leading-5 text-slate-500">Analytics are calculated locally by the backend. AI explanations use your private Ollama instance.</p></div><div className="mt-4 flex items-center gap-3 rounded-xl p-2"><div className="grid h-9 w-9 place-items-center rounded-full bg-slate-100 text-xs font-bold">{user?.email?.slice(0,1).toUpperCase()||'S'}</div><div className="min-w-0 flex-1"><div className="truncate text-xs font-semibold">{user?.workspace_name||'Loading workspace'}</div><div className="truncate text-[10px] text-slate-400">{user?.email}</div></div><button aria-label="Sign out" onClick={signOut}><LogOut size={15} className="text-slate-400"/></button></div></aside>

  <main className="min-w-0 flex-1 px-4 pb-12 md:px-8 lg:px-10"><header className="flex min-h-[78px] items-center justify-between border-b border-slate-200/70"><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-forest text-white lg:hidden"><Boxes size={19}/></div><div><div className="text-xs text-slate-400">Workspace / {section}</div><h1 className="mt-0.5 text-lg font-semibold">{section==='Overview'?'Good morning':section}</h1></div></div><div className="flex items-center gap-2"><div className="hidden items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-2 sm:flex"><span className={`h-2 w-2 rounded-full ${ai?.model_available?'bg-emerald-500':ai?.connected?'bg-amber-400':'bg-slate-300'}`}/><span className="text-xs text-slate-500">{ai?.model_available?'Gemma connected':ai?.connected?'Model missing':'AI offline'}</span></div><button onClick={showReport} className="flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-semibold hover:bg-slate-50"><Download size={14}/> <span className="hidden sm:inline">Export</span></button><div className="flex items-center gap-1 rounded-lg border border-slate-200 bg-white px-2 py-2"><select value={storeId} onChange={e=>setStoreId(e.target.value)} className="max-w-[118px] bg-transparent text-xs font-medium outline-none">{stores.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select><ChevronDown size={13} className="text-slate-400"/></div></div></header>

  <div className="mt-6 flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-xl font-semibold tracking-tight">{section==='Overview'?'Your store at a glance':section}</h2><p className="mt-1 text-xs text-slate-400">{facts?`${facts.period.start} — ${facts.period.end}`:'Loading your data'}</p></div><div className="flex gap-2"><input aria-label="Start date" type="date" value={start} onChange={e=>setStart(e.target.value)} className="rounded-lg border border-slate-200 bg-white px-2.5 py-2 text-xs"/><input aria-label="End date" type="date" value={end} onChange={e=>setEnd(e.target.value)} className="rounded-lg border border-slate-200 bg-white px-2.5 py-2 text-xs"/><button onClick={()=>{setStart('');setEnd('')}} className="rounded-lg border border-slate-200 bg-white px-3 text-xs text-slate-500">30 days</button></div></div>

  {error&&<div className="mt-5 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">{error}</div>}{notice&&<div className="mt-5 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-800">{notice}<button onClick={()=>setNotice('')} className="float-right">×</button></div>}

  {loading&&!facts?<div className="mt-12 flex justify-center text-forest"><LoaderCircle className="animate-spin"/></div>:!facts?<div className="mt-8 rounded-2xl bg-white p-8 text-sm text-slate-500">Connect to the StockSense API to load store data.</div>:<>

   {(section==='Overview'||section==='Sales analytics')&&<><div className="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{statCards.map(([label,value,hint,Icon])=><div key={label} className="rounded-2xl border border-slate-100 bg-white p-5 shadow-soft"><div className="flex items-center justify-between"><span className="text-xs font-medium text-slate-500">{label}</span><span className="text-forest">{Icon}</span></div><div className="mt-4 text-[26px] font-semibold tracking-tight">{value}</div><div className="mt-2 flex items-start gap-1.5 text-[10px] leading-4 text-slate-400"><CircleHelp size={12} className="mt-0.5 shrink-0"/>{hint}</div></div>)}</div><div className="mt-5 rounded-2xl border border-slate-100 bg-white p-5 shadow-soft"><div className="flex flex-wrap items-center justify-between gap-3"><div><div className="flex items-center gap-2"><span className="grid h-8 w-8 place-items-center rounded-lg bg-mint text-forest"><Activity size={16}/></span><h3 className="text-sm font-semibold">Daily action center</h3></div><p className="mt-1 text-xs text-slate-400">Review the highest-value tasks from your recorded sales and stock.</p></div><span className="rounded-full bg-slate-50 px-2.5 py-1 text-[10px] font-semibold text-slate-500">{facts.action_center?.length||0} actions</span></div><div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{(facts.action_center||[]).slice(0,3).map((action:any)=><div key={`${action.type}-${action.sku||action.title}`} className="rounded-xl border border-slate-100 bg-[#fbfcfb] p-4"><div className="flex items-center justify-between gap-2"><div className="text-xs font-semibold">{action.title}</div><span className={`rounded-full px-2 py-1 text-[9px] font-bold uppercase ${action.priority==="high"?"bg-rose-50 text-rose-700":action.priority==="medium"?"bg-amber-50 text-amber-700":"bg-slate-100 text-slate-500"}`}>{action.priority}</span></div><p className="mt-2 text-[11px] leading-5 text-slate-500">{action.detail}</p><div className="mt-3 flex items-center justify-between gap-3"><div className="text-[10px] font-semibold text-forest">{action.action}</div><button onClick={()=>{if(action.type==='complete_costs'){setSection('Products')}else{setSection('Inventory');const product=products.find(p=>p.sku===action.sku);if(product){setMovementProduct(String(product.id));if(action.type==='count_stock')setMovementType('count')}}}} className="shrink-0 rounded-lg bg-white px-2.5 py-1.5 text-[10px] font-semibold text-forest shadow-sm">{action.type==='count_stock'?'Enter count':action.type==='complete_costs'?'Add costs':'Review item'}</button></div></div>)}{!facts.action_center?.length&&<div className="rounded-xl bg-emerald-50/70 p-4 text-xs text-emerald-800 sm:col-span-2 xl:col-span-3">You’re caught up. No review actions were calculated for the current data.</div>}</div><button onClick={()=>setSection("Inventory")} className="mt-4 text-xs font-semibold text-forest">Open inventory workflow →</button></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.65fr_1fr]"><div className="rounded-2xl border border-slate-100 bg-white p-5 shadow-soft"><div className="flex items-start justify-between"><div><h3 className="text-sm font-semibold">Sales performance</h3><p className="mt-1 text-xs text-slate-400">Net sales by transaction date</p></div><button className="rounded-lg bg-slate-50 px-2.5 py-1.5 text-[10px] text-slate-500">Daily <ChevronDown size={12} className="inline"/></button></div><div className="mt-5 h-[260px]">{facts.trend.length?<ResponsiveContainer width="100%" height="100%"><AreaChart data={facts.trend}><defs><linearGradient id="colorRevenue" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#18845c" stopOpacity={.22}/><stop offset="100%" stopColor="#18845c" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#edf1ee" vertical={false}/><XAxis dataKey="date" tickFormatter={(s)=>s.slice(5)} axisLine={false} tickLine={false} tick={{fontSize:10,fill:'#8a9891'}} minTickGap={24}/><YAxis axisLine={false} tickLine={false} tick={{fontSize:10,fill:'#8a9891'}} tickFormatter={(v)=>`₹${Math.round(v/1000)}k`} width={44}/><Tooltip formatter={(v:any)=>money(v)} labelStyle={{fontSize:11}} contentStyle={{borderRadius:12,border:'1px solid #e9eeeb',fontSize:12}}/><Area type="monotone" dataKey="revenue" name="Net sales" stroke="#168454" strokeWidth={2.5} fill="url(#colorRevenue)"/></AreaChart></ResponsiveContainer>:<Empty text="No sales in this period. Import a file to start."/>}</div></div><div className="rounded-2xl border border-slate-100 bg-white p-5 shadow-soft"><div className="flex items-center justify-between"><div><h3 className="text-sm font-semibold">Top products</h3><p className="mt-1 text-xs text-slate-400">Ranked by net sales</p></div><button onClick={()=>setSection('Products')} className="text-[11px] font-semibold text-forest">View all</button></div><div className="mt-3 divide-y divide-slate-100">{facts.top_products_by_sales.slice(0,5).map((p:any,i:number)=><div key={p.sku} className="flex items-center gap-3 py-3"><div className="grid h-8 w-8 place-items-center rounded-lg bg-mint text-[11px] font-bold text-forest">{String(i+1).padStart(2,'0')}</div><div className="min-w-0 flex-1"><div className="truncate text-xs font-semibold">{p.name}</div><div className="mt-1 text-[10px] text-slate-400">{p.units} units · {p.sku}</div></div><div className="text-xs font-semibold">{money(p.net_sales)}</div></div>)}</div></div></div><div className="mt-5 grid gap-5 lg:grid-cols-2"><div className="rounded-2xl border border-slate-100 bg-white p-5 shadow-soft"><div className="flex items-center justify-between"><div><h3 className="text-sm font-semibold">Needs attention</h3><p className="mt-1 text-xs text-slate-400">Products at or below their reorder threshold</p></div><span className="rounded-full bg-amber-50 px-2.5 py-1 text-[10px] font-semibold text-amber-700">{facts.low_stock.length} alerts</span></div><div className="mt-4 space-y-2">{facts.low_stock.slice(0,4).map((p:any)=><div key={p.sku} className="flex items-center justify-between rounded-xl bg-slate-50 px-3 py-2.5"><div className="text-xs font-medium">{p.name}<span className="ml-2 text-[10px] text-slate-400">{p.sku}</span></div><span className="rounded-lg bg-white px-2 py-1 text-[10px] font-semibold text-amber-700">{p.stock} left</span></div>)}{!facts.low_stock.length&&<Empty text="No products currently cross the configured stock threshold."/>}</div></div><div className="rounded-2xl border border-emerald-100 bg-gradient-to-br from-[#f3faf5] to-white p-5"><div className="flex items-center gap-2 text-forest"><div className="grid h-8 w-8 place-items-center rounded-lg bg-white shadow-sm"><Sparkles size={16}/></div><h3 className="text-sm font-semibold">This week, based on your data</h3></div><div className="mt-4 space-y-3">{facts.reorder_suggestions.slice(0,2).map((p:any)=><div key={p.sku} className="flex gap-3"><span className="mt-1 h-1.5 w-1.5 shrink-0 rounded-full bg-forest"/><div><div className="text-xs font-semibold">{p.suggested_reorder?`Review reorder for ${p.name}`:`Track demand for ${p.name}`}</div><p className="mt-1 text-[11px] leading-5 text-slate-500">{p.suggested_reorder?`${p.suggested_reorder} units suggested from recent demand, ${p.lead_time_days}-day lead time and threshold safety stock.`:'No recent sales in the selected window; no reorder quantity is inferred.'}</p></div></div>)}</div><button onClick={()=>setSection('Inventory')} className="mt-4 text-xs font-semibold text-forest">Review inventory <span>→</span></button></div></div></>}

{section==='Inventory'&&<><div className="mt-6 grid gap-4 sm:grid-cols-3"><Mini label="Inventory cost value" value={money(facts.inventory_cost_value)} sub="Current stock × current unit cost"/><Mini label="Below reorder threshold" value={facts.low_stock.length} sub="Based on your configured thresholds"/><Mini label="Products with stock data" value={products.filter(p=>p.stock_on_hand!==null).length} sub={`of ${products.length} active products`}/></div><Table title="Reorder suggestions" sub="Recent average demand; review assumptions before buying" headers={['Product','On hand','Daily demand','Days left','Lead time','Suggested qty']} rows={facts.reorder_suggestions.map((p:any)=>[<b>{p.name}</b>,p.stock??'Unknown',fmt(p.daily_demand),fmt(p.days_remaining),`${p.lead_time_days} days`,<span className="rounded-md bg-emerald-50 px-2 py-1 font-semibold text-forest">{p.suggested_reorder}</span>])}/><div className="mt-5 grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><section className="rounded-2xl border border-slate-100 bg-white p-5 shadow-soft"><div className="text-sm font-semibold">Record a stock movement</div><p className="mt-1 text-xs leading-5 text-slate-500">Counts, deliveries, damage, and corrections update on-hand stock and create an audit entry.</p><form onSubmit={recordMovement} className="mt-4 space-y-3"><label className="block text-xs font-medium text-slate-600">Product<select required value={movementProduct} onChange={e=>setMovementProduct(e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm"><option value="">Choose a product</option>{products.map(p=><option key={p.id} value={p.id}>{p.name} · {p.sku}{p.stock_on_hand==null?' · stock unknown':` · ${p.stock_on_hand} on hand`}</option>)}</select></label><label className="block text-xs font-medium text-slate-600">Movement type<select value={movementType} onChange={e=>setMovementType(e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm"><option value="count">Physical stock count (set current total)</option><option value="receive">Delivery received (add units)</option><option value="damage">Damaged or removed (subtract units)</option><option value="correction">Correction (set current total)</option></select></label><label className="block text-xs font-medium text-slate-600">{movementType==='count'||movementType==='correction'?'Counted on-hand units':'Units'}<input required type="number" min="0" step="1" value={movementQuantity} onChange={e=>setMovementQuantity(e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-200 px-3 py-2 text-sm"/></label><label className="block text-xs font-medium text-slate-600">Note (optional)<input maxLength={500} value={movementNote} onChange={e=>setMovementNote(e.target.value)} placeholder="e.g. shelf count, invoice, damaged units" className="mt-1 block w-full rounded-lg border border-slate-200 px-3 py-2 text-sm"/></label><button disabled={!movementProduct||movementQuantity===''||movementBusy||(movementType==='receive'&&products.find(p=>String(p.id)===movementProduct)?.stock_on_hand==null)} className="rounded-lg bg-forest px-4 py-2.5 text-xs font-semibold text-white disabled:cursor-not-allowed disabled:opacity-40">{movementBusy?'Saving movement…':'Save movement'}</button><p className="text-[10px] leading-4 text-slate-400">A delivery can be recorded after an opening count is known. Historical sales imports do not silently change today’s stock.</p></form></section><div><Table title="Stock movement history" sub="Latest 30 changes, newest first" headers={['When','Product','Type','Change','After','Note']} rows={movements.map((item:any)=>[new Date(item.created_at+'Z').toLocaleString(),<b>{item.product}</b>,item.movement_type.replaceAll('_',' '),`${item.quantity_delta>0?'+':''}${item.quantity_delta}`,item.quantity_after,item.note||'—'])}/></div></div><p className="mt-4 text-xs text-slate-400">{facts.limitations.join(' ')}</p></>}

   {section==='Products'&&<><div className="mt-6 flex items-center justify-between rounded-2xl bg-white p-4 shadow-soft"><div className="flex items-center gap-2"><Search size={16} className="text-slate-400"/><input placeholder="Search products or SKU" value={query} onChange={e=>setQuery(e.target.value)} className="w-56 outline-none text-sm"/></div><span className="text-xs text-slate-400">{products.filter(p=>(p.name+p.sku+p.category).toLowerCase().includes(query.toLowerCase())).length} products</span></div><Table title="Product catalog" sub="Cost is optional; profitability appears only when historical cost is available" headers={['Product','SKU','Category','Selling price','Unit cost','Stock']} rows={products.filter(p=>(p.name+p.sku+p.category).toLowerCase().includes(query.toLowerCase())).map((p:any)=>[<b>{p.name}</b>,p.sku,p.category,money(p.unit_price),<input aria-label={`Unit cost for ${p.name}`} type="number" min="0" step="0.01" defaultValue={p.unit_cost??''} placeholder="Add cost" onBlur={e=>{if(e.target.value!==(p.unit_cost==null?'':String(p.unit_cost)))saveProductCost(p.id,e.target.value)}} className="w-28 rounded-md border border-slate-200 bg-white px-2 py-1 text-xs"/>,p.stock_on_hand??'Unknown'])}/></>}

   {section==='Finance'&&<><div className="mt-6 grid gap-4 sm:grid-cols-3"><Mini label="Gross profit" value={money(m?.gross_profit)} sub="Net sales less cost of goods sold"/><Mini label="Gross margin" value={m?.gross_margin_pct==null?'Insufficient data':`${fmt(m.gross_margin_pct)}%`} sub="Gross profit divided by net sales"/><Mini label="Inventory capital" value={money(facts.inventory_cost_value)} sub="Current-cost estimate; not a historical valuation"/></div><div className="mt-5 grid gap-5 xl:grid-cols-2"><Table title="Highest gross profit" sub="Only products with available cost data" headers={['Product','Units','Net sales','Gross profit','Margin']} rows={facts.top_products_by_profit.map((p:any)=>[<b>{p.name}</b>,p.units,money(p.net_sales),money(p.gross_profit),p.gross_margin_pct==null?'—':`${fmt(p.gross_margin_pct)}%`])}/><div className="rounded-2xl border border-slate-100 bg-white p-5 shadow-soft"><h3 className="text-sm font-semibold">Purchase budget planner</h3><p className="mt-1 text-xs leading-5 text-slate-400">Ranks current reorder suggestions by days remaining and uses recorded unit costs. Review every suggestion before buying.</p><form onSubmit={planBudget} className="mt-4 flex items-end gap-2"><label className="flex-1 text-[10px] font-semibold text-slate-400">Available budget (₹)<input type="number" min="0" step="0.01" value={budget} onChange={e=>setBudget(e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-200 px-3 py-2 text-sm text-ink" aria-label="Available purchase budget in INR"/></label><button className="rounded-lg bg-forest px-3 py-2.5 text-xs font-semibold text-white">Plan budget</button></form>{budgetPlan&&<div className="mt-4"><div className="flex justify-between text-xs"><span>Proposed spend</span><b>{money(Number(budgetPlan.budget)-Number(budgetPlan.budget_remaining))}</b></div><div className="mt-1 flex justify-between text-xs text-slate-500"><span>Budget remaining</span><b>{money(budgetPlan.budget_remaining)}</b></div><div className="mt-3 max-h-48 space-y-2 overflow-auto">{budgetPlan.allocations.map((p:any)=><div key={p.sku} className="rounded-lg bg-slate-50 p-3 text-xs"><div className="flex justify-between font-semibold"><span>{p.product} × {p.quantity}</span><span>{money(p.estimated_purchase_cost)}</span></div><div className="mt-1 text-[10px] text-slate-400">{p.stockout_risk} risk · {fmt(p.days_remaining)} days remaining</div></div>)}{!budgetPlan.allocations.length&&<p className="text-xs text-slate-400">No cost-supported reorder suggestion fits this budget.</p>}</div><p className="mt-3 text-[10px] leading-4 text-slate-400">{budgetPlan.assumptions.join(' ')}</p></div>}</div><div className="rounded-2xl border border-slate-100 bg-white p-5 shadow-soft xl:col-span-2"><h3 className="text-sm font-semibold">Financial assumptions</h3><ul className="mt-4 space-y-3 text-xs leading-5 text-slate-500">{facts.limitations.map((x,i)=><li key={i} className="flex gap-2"><span className="text-forest">•</span>{x}</li>)}</ul></div></div></>}

   {section==='Marketing insights'&&<><div className="mt-6 grid gap-4 sm:grid-cols-3"><Mini label="Basket transactions" value={marketing?.basket_count??'—'} sub="Distinct transaction IDs with sale items"/><Mini label="Co-purchase patterns" value={marketing?.bundling_opportunities?.length??'—'} sub="Pairs appearing in at least two baskets"/><Mini label="Excess-stock candidates" value={marketing?.excess_stock_candidates?.length??'—'} sub="Heuristic review list, not a dead-stock label"/></div><div className="mt-5 grid gap-5 xl:grid-cols-2"><Table title="Co-purchase opportunities" sub="Association is not causation; use these pairs as tests" headers={['Product','Often with','Support','Confidence','Lift','Baskets']} rows={(marketing?.bundling_opportunities||[]).map((r:any)=>[<b>{r.product}</b>,r.often_with,`${fmt(Number(r.support)*100)}%`,`${fmt(Number(r.confidence)*100)}%`,fmt(r.lift),r.transactions])}/><Table title="Excess-stock candidates" sub="Simple recent average demand; review before promoting" headers={['Product','Stock','Units sold','Days of cover','Reason']} rows={(marketing?.excess_stock_candidates||[]).map((p:any)=>[<b>{p.product}</b>,p.stock,p.units_sold,fmt(p.estimated_days_of_cover),p.rationale])}/></div><div className="mt-5 rounded-xl bg-white p-4 text-xs leading-5 text-slate-500">{(marketing?.limitations||['Loading marketing facts…']).join(' ')}</div></>}

   {section==='Ask StockSense'&&<section className="mx-auto mt-8 max-w-5xl">
    <div className="relative overflow-hidden rounded-[28px] border border-emerald-100 bg-gradient-to-br from-[#e9f6ee] via-[#f4faf6] to-white px-6 py-7 sm:px-9 sm:py-9">
     <div className="absolute -right-10 -top-16 h-56 w-56 rounded-full bg-emerald-100/60 blur-3xl"/>
     <div className="relative flex flex-wrap items-start justify-between gap-5">
      <div className="max-w-2xl">
       <div className="inline-flex items-center gap-2 rounded-full border border-emerald-200/80 bg-white/80 px-3 py-1.5 text-[11px] font-semibold uppercase tracking-[.12em] text-forest"><Sparkles size={14}/> StockSense analyst</div>
       <h2 className="mt-5 text-3xl font-semibold tracking-[-.045em] text-ink sm:text-[40px] sm:leading-[1.08]">Ask a better question.<br className="hidden sm:block"/> Get an answer grounded in your store.</h2>
       <p className="mt-4 max-w-xl text-sm leading-6 text-slate-600">Explore sales, products, margins, and stock with answers based on the records in your selected date range.</p>
      </div>
      <div className="hidden rounded-2xl border border-white/80 bg-white/75 p-4 shadow-sm sm:block"><div className="flex items-center gap-2 text-xs font-semibold text-forest"><span className={`h-2 w-2 rounded-full ${ai?.model_available?'bg-emerald-500':'bg-amber-400'}`}/>{ai?.model_available?'AI ready to analyze':'AI model unavailable'}</div><div className="mt-3 grid grid-cols-2 gap-2">{['Sales','Products','Margins','Stock'].map(label=><span key={label} className="rounded-lg bg-[#f2f7f4] px-3 py-2 text-[11px] font-medium text-slate-600">{label}</span>)}</div></div>
     </div>
     <div className="relative mt-6 flex flex-wrap items-center gap-x-5 gap-y-2 border-t border-emerald-900/10 pt-4 text-xs text-slate-500"><span className="font-semibold text-slate-700">Current scope</span><span>{facts.period.start} – {facts.period.end}</span><span>{stores.find(s=>String(s.id)===storeId)?.name||'Selected store'}</span><span>{fmt(m?.transactions)} transactions</span></div>
    </div>

    <form onSubmit={ask} className="relative mt-5 rounded-[24px] border border-slate-200/90 bg-white p-3 shadow-[0_18px_55px_rgba(27,69,48,.08)] transition focus-within:border-emerald-300 focus-within:ring-4 focus-within:ring-emerald-900/[.04] sm:p-4">
     <label htmlFor="ai-question" className="sr-only">Ask StockSense about your data</label>
     <textarea id="ai-question" rows={3} value={question} onChange={e=>setQuestion(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&(e.metaKey||e.ctrlKey)){e.preventDefault();e.currentTarget.form?.requestSubmit()}}} placeholder="Ask anything about your sales, products, or inventory…" className="w-full resize-y border-0 bg-transparent px-3 py-2 text-[15px] leading-6 text-ink outline-none placeholder:text-slate-400 focus-visible:outline-none"/>
     <div className="flex flex-wrap items-center justify-between gap-3 border-t border-slate-100 px-2 pt-3"><span className="text-[11px] text-slate-400">Try “Which products should I focus on to increase sales?” <span className="hidden sm:inline">· Ctrl/⌘ + Enter to ask</span></span><button disabled={!question.trim()||asking} className="inline-flex items-center gap-2 rounded-xl bg-forest px-4 py-2.5 text-xs font-semibold text-white shadow-sm transition hover:bg-emerald-800 disabled:cursor-not-allowed disabled:opacity-45">{asking?<LoaderCircle size={15} className="animate-spin"/>:<Send size={14}/>} {asking?'Analyzing':'Ask StockSense'}</button></div>
    </form>

    {!chatMessages.length&&<div className="mt-7"><div className="flex items-end justify-between gap-3"><div><div className="text-sm font-semibold tracking-tight">Start with a question</div><p className="mt-1 text-xs text-slate-500">Choose a prompt or write your own.</p></div><span className="hidden text-[11px] text-slate-400 sm:block">Suggestions use the current store and date range</span></div><div className="mt-3 grid gap-3 sm:grid-cols-2">{[
      ['Sales opportunities','What changes could help me sell more?'],
      ['Product performance','Which product sold the most units?'],
      ['Profitability','Which product generated the highest gross profit?'],
      ['Inventory planning','What stock should I review for reorder?'],
     ].map(([label,prompt])=><button type="button" key={label} onClick={()=>setQuestion(prompt)} className="group flex items-center justify-between rounded-2xl border border-slate-200/80 bg-white px-4 py-4 text-left transition hover:-translate-y-0.5 hover:border-emerald-200 hover:shadow-soft"><span><span className="block text-[10px] font-semibold uppercase tracking-[.12em] text-forest">{label}</span><span className="mt-1.5 block text-sm font-medium text-slate-700">{prompt}</span></span><span className="ml-3 grid h-8 w-8 shrink-0 place-items-center rounded-full bg-slate-50 text-slate-400 transition group-hover:bg-mint group-hover:text-forest"><ArrowUpRight size={15}/></span></button>)}
     </div></div>}

    {!!chatMessages.length&&<div className="mt-8 flex items-center justify-between border-b border-slate-200 pb-3"><div><h3 className="text-sm font-semibold">Analysis</h3><p className="mt-1 text-xs text-slate-500">Answers are tied to the selected store and date range.</p></div><button type="button" onClick={()=>setChatMessages([])} className="rounded-lg px-3 py-2 text-xs font-semibold text-slate-500 transition hover:bg-white hover:text-forest">New conversation</button></div>}
    <div className="mt-5 space-y-7">{chatMessages.map((message,index)=><article key={`${index}-${message.question}`} className="space-y-4">
     <div className="flex justify-end"><div className="max-w-[85%] rounded-2xl rounded-br-md bg-forest px-4 py-3 text-sm leading-6 text-white shadow-sm">{message.question}</div></div>
     <div className="flex items-start gap-3"><div className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-mint text-forest"><Sparkles size={17}/></div><div className="min-w-0 flex-1 rounded-2xl border border-slate-200/80 bg-white p-5 shadow-soft sm:p-6">{message.loading?<div className="flex items-center gap-3 py-1 text-sm text-slate-500"><LoaderCircle size={17} className="animate-spin text-forest"/>Reviewing your store data…</div>:<><div className="mb-4 flex items-center gap-2 text-[10px] font-semibold uppercase tracking-[.12em] text-forest"><span>Data analysis</span><span className="h-1 w-1 rounded-full bg-emerald-300"/><span>{!message.evidence?'Unavailable':message.evidence.answer_source==='gemma'?`Gemma · ${message.evidence.model||ai?.model}`:message.evidence.answer_source==='core_analytics_fallback'?'Core analytics · Gemma unavailable':'Core analytics'}</span></div><AnswerContent text={message.answer||''}/>{message.evidence&&<div className="mt-6 rounded-xl border border-slate-100 bg-slate-50/70 p-4"><div className="flex flex-wrap items-center justify-between gap-2 text-xs"><b className="text-slate-700">Evidence for this answer</b><span className="text-slate-400">{message.evidence.period.start} – {message.evidence.period.end}</span></div><div className="mt-3 grid gap-3 text-xs sm:grid-cols-2 xl:grid-cols-4"><span className="text-slate-500">Net sales <b className="ml-1 text-slate-800">{money(message.evidence.metrics.net_sales)}</b></span><span className="text-slate-500">Gross profit <b className="ml-1 text-slate-800">{money(message.evidence.metrics.gross_profit)}</b></span><span className="text-slate-500">Gross margin <b className="ml-1 text-slate-800">{message.evidence.metrics.gross_margin_pct==null?'—':`${fmt(message.evidence.metrics.gross_margin_pct)}%`}</b></span><span className="text-slate-500">Net units <b className="ml-1 text-slate-800">{fmt(message.evidence.metrics.net_units)}</b></span></div>{message.evidence.products?.length>0&&<div className="mt-4 border-t border-slate-100 pt-3"><div className="mb-2 text-[10px] font-semibold uppercase tracking-wide text-slate-400">Product records used</div><div className="space-y-2">{message.evidence.products.slice(0,5).map((product:any)=><div key={product.sku} className="flex flex-wrap items-center justify-between gap-2 text-xs"><span className="font-medium text-slate-700">{product.name} <span className="text-slate-400">· {product.sku}</span></span><span className="text-slate-500">{fmt(product.units??product.net_units)} net units · {money(product.net_sales)} net sales{product.gross_profit!=null?` · ${money(product.gross_profit)} gross profit`:''}</span></div>)}</div></div>}{message.evidence.inventory?.length>0&&<div className="mt-4 border-t border-slate-100 pt-3"><div className="mb-2 text-[10px] font-semibold uppercase tracking-wide text-slate-400">Inventory signals used</div><div className="space-y-2">{message.evidence.inventory.slice(0,5).map((item:any,index:number)=><div key={`${item.sku||item.product||item.name}-${index}`} className="text-xs text-slate-600"><b className="text-slate-700">{item.product||item.name||item.title}</b>{item.detail?` — ${item.detail}`:item.suggested_reorder!=null?` — ${item.suggested_reorder} suggested units, ${fmt(item.days_remaining)} days remaining`:''}</div>)}</div></div>}</div>}</>}</div></div>
    </article>)}</div>
   </section>}

   {section==='Imports'&&<div className="mt-6 max-w-3xl rounded-2xl border border-slate-100 bg-white p-6 shadow-soft"><h3 className="text-sm font-semibold">Import sales history</h3><p className="mt-2 text-xs leading-5 text-slate-500">Upload CSV or Excel. Preview detected columns, then confirm. Invalid and duplicate rows are reported and never silently discarded.</p><div className="mt-5 rounded-2xl border-2 border-dashed border-slate-200 bg-slate-50/50 p-8 text-center"><Upload size={22} className="mx-auto text-forest"/><div className="mt-3 text-sm font-medium">Choose a CSV or Excel file</div><div className="mt-1 text-xs text-slate-400">Up to 15 MB</div><input type="file" accept=".csv,.xlsx,.xls" onChange={e=>setFile(e.target.files?.[0]||null)} className="mt-4 block w-full text-xs file:mr-3 file:rounded-lg file:border-0 file:bg-forest file:px-3 file:py-2 file:text-xs file:font-semibold file:text-white"/><button disabled={!file} onClick={previewImport} className="mt-4 rounded-xl bg-forest px-4 py-2.5 text-xs font-semibold text-white disabled:opacity-40">Preview columns</button></div>{preview&&<div className="mt-5 rounded-xl border border-slate-100 p-4"><div className="flex items-center justify-between"><div><div className="text-sm font-semibold">{preview.filename}</div><div className="mt-1 text-xs text-slate-400">{preview.rows} rows · {preview.columns.length} columns</div></div><button onClick={confirmImport} disabled={!preview.suggested_mapping.date||!preview.suggested_mapping.quantity||!preview.suggested_mapping.unit_price} className="rounded-lg bg-forest px-3 py-2 text-xs font-semibold text-white disabled:opacity-40">Confirm import</button></div><div className="mt-4 grid gap-2 sm:grid-cols-2">{[['date','Date'],['transaction_id','Transaction ID'],['sku','Product SKU'],['product_name','Product name'],['category','Category'],['quantity','Quantity'],['unit_price','Unit price'],['discount','Discount'],['tax','Tax'],['unit_cost','Unit cost'],['return','Return flag']].map(([field,label])=><label key={field} className="flex items-center justify-between gap-2 rounded-lg bg-slate-50 px-3 py-2 text-[11px] text-slate-500">{label}<select value={preview.suggested_mapping[field]||''} onChange={e=>setPreview({...preview,suggested_mapping:{...preview.suggested_mapping,[field]:e.target.value}})} className="max-w-[55%] rounded-md border border-slate-200 bg-white px-2 py-1 text-[10px]"><option value="">Not mapped</option>{preview.columns.map((c:string)=><option key={c} value={c}>{c}</option>)}</select></label>)}</div>{(!preview.suggested_mapping.date||!preview.suggested_mapping.quantity||!preview.suggested_mapping.unit_price)&&<p className="mt-2 text-xs text-red-600">Map date, quantity and unit price to continue.</p>}<div className="mt-3 max-h-36 overflow-auto rounded-lg bg-slate-50 p-3 text-[10px] text-slate-500">{preview.sample.slice(0,3).map((r:any,i:number)=><pre key={i}>{JSON.stringify(r)}</pre>)}</div></div>}</div>}

   {section==='Reports'&&<div className="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{[['Performance summary','Period totals, product ranking, definitions'],['Inventory and reorder','Stock levels, demand rate, reorder assumptions'],['Financial summary','Gross profit, margin, inventory cost value']].map(([title,sub])=><div key={title} className="rounded-2xl border border-slate-100 bg-white p-5 shadow-soft"><div className="grid h-9 w-9 place-items-center rounded-xl bg-mint text-forest"><FileSpreadsheet size={17}/></div><h3 className="mt-4 text-sm font-semibold">{title}</h3><p className="mt-1 min-h-9 text-xs leading-5 text-slate-400">{sub}</p><button onClick={showReport} className="mt-3 flex items-center gap-2 text-xs font-semibold text-forest"><Download size={14}/>Download CSV report</button></div>)}</div>}

  {section==='Settings'&&<div className="mt-6 max-w-2xl rounded-2xl bg-white p-6 shadow-soft"><h3 className="text-sm font-semibold">Workspace settings</h3><div className="mt-4 grid gap-4 sm:grid-cols-2"><div><div className="text-[10px] font-bold uppercase tracking-wider text-slate-400">Workspace</div><div className="mt-1 text-sm">{user?.workspace_name}</div></div><div><div className="text-[10px] font-bold uppercase tracking-wider text-slate-400">Currency / timezone</div><div className="mt-1 text-sm">INR · Asia/Kolkata</div></div></div><p className="mt-5 text-xs leading-5 text-slate-500">Authentication uses a signed, HttpOnly session cookie. This local build uses SQLite by default. Set PostgreSQL and a production secret before deployment.</p></div>}

  </>}</main><div aria-label="Main navigation" className="fixed bottom-0 left-0 right-0 z-10 flex gap-1 overflow-x-auto border-t border-slate-200 bg-white px-2 py-2 lg:hidden">{nav.map(({name,icon:Icon})=><button key={name} onClick={()=>setSection(name)} className={`flex min-w-[68px] flex-1 flex-col items-center gap-1 rounded-lg py-1 text-[9px] ${section===name?'text-forest':'text-slate-400'}`}><Icon size={16}/>{name.split(' ')[0]}</button>)}</div></div>

}

function InlineMarkdown({text}:{text:string}){
 const parts=text.split(/(\*\*[^*]+\*\*|__[^_]+__|`[^`]+`|\*[^*]+\*)/g);
 return <>{parts.map((part,index)=>{
  if((part.startsWith('**')&&part.endsWith('**'))||(part.startsWith('__')&&part.endsWith('__')))return <strong key={index}>{part.slice(2,-2)}</strong>;
  if(part.startsWith('`')&&part.endsWith('`'))return <code key={index}>{part.slice(1,-1)}</code>;
  if(part.startsWith('*')&&part.endsWith('*'))return <em key={index}>{part.slice(1,-1)}</em>;
  return <span key={index}>{part}</span>;
 })}</>;
}

function AnswerContent({text}:{text:string}){
 const blocks:React.ReactNode[]=[];
 let paragraph:string[]=[];
 let list:{ordered:boolean;items:string[]}|null=null;
 const flushParagraph=()=>{if(paragraph.length){blocks.push(<p key={`p-${blocks.length}`}><InlineMarkdown text={paragraph.join(' ')}/></p>);paragraph=[]}};
 const flushList=()=>{if(list){const List=list.ordered?'ol':'ul';blocks.push(<List key={`list-${blocks.length}`}>{list.items.map((item,index)=><li key={index}><InlineMarkdown text={item}/></li>)}</List>);list=null}};
 for(const rawLine of text.split(/\r?\n/)){
  const line=rawLine.trim();
  if(!line){flushParagraph();flushList();continue}
  if(/^```/.test(line)||/^[-*_]{3,}$/.test(line))continue;
  const heading=line.match(/^(#{1,3})\s+(.+)$/);
  if(heading){flushParagraph();flushList();const Heading=heading[1].length===1?'h2':'h3';blocks.push(<Heading key={`h-${blocks.length}`}><InlineMarkdown text={heading[2]}/></Heading>);continue}
  const item=line.match(/^([-*+]|\d+[.)])\s+(.+)$/);
  if(item){flushParagraph();const ordered=/^\d/.test(item[1]);if(list&&list.ordered!==ordered)flushList();if(!list)list={ordered,items:[]};list.items.push(item[2]);continue}
  flushList();paragraph.push(line);
 }
 flushParagraph();flushList();
 return <div className="answer-content space-y-3 text-[14px] leading-7 text-slate-600">{blocks}</div>;
}

function Empty({text}:{text:string}){return <div className="grid h-full place-items-center px-4 text-center text-xs text-slate-400">{text}</div>}

function Mini({label,value,sub}:{label:string;value:any;sub:string}){return <div className="rounded-2xl border border-slate-100 bg-white p-5 shadow-soft"><div className="text-xs font-medium text-slate-500">{label}</div><div className="mt-3 text-2xl font-semibold">{value}</div><div className="mt-2 text-[10px] text-slate-400">{sub}</div></div>}

function Table({title,sub,headers,rows}:{title:string;sub:string;headers:string[];rows:any[][]}){return <div className="mt-5 overflow-hidden rounded-2xl border border-slate-100 bg-white shadow-soft"><div className="p-5"><h3 className="text-sm font-semibold">{title}</h3><p className="mt-1 text-xs text-slate-400">{sub}</p></div><div className="scrollbar overflow-x-auto"><table className="w-full min-w-[650px] text-left text-xs"><thead><tr className="border-y border-slate-100 bg-slate-50/70">{headers.map(h=><th key={h} className="px-5 py-3 text-[10px] font-semibold uppercase tracking-wide text-slate-400">{h}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={i} className="border-b border-slate-50 last:border-0">{r.map((v,j)=><td key={j} className="px-5 py-3.5 text-slate-600">{v}</td>)}</tr>)}</tbody></table>{!rows.length&&<div className="p-6 text-center text-xs text-slate-400">No records for this period.</div>}</div></div>}
